// gdn_cpu.cpp - plain-fp32 reference implementation of the GDN step chain.
// This is the ground truth the CUDA kernels and the golden vectors
// (tests/gdn_vectors.hpp, generated by scripts/gen_gdn_vectors.py) are
// checked against. Deliberately unsophisticated: clarity over speed - the
// fast paths live in src/kernels/cuda/gdn.cu.
#include "sager/kernels/gdn.hpp"
#include "sager/kernels/q4_k.hpp"

#include <cmath>
#include <cstring>
#include <vector>

namespace sager::gdn_cpu {
namespace {

inline float h2f(uint16_t h) { return q4k::half_to_float(h); }
inline uint16_t f2h(float f) { return q4k::float_to_half(f); }

inline float sigmoidf(float x) { return 1.f / (1.f + std::exp(-x)); }

// log(1 + exp(x)) without overflow (mirrors torch.nn.functional.softplus)
inline float softplusf(float x) {
  if (x > 20.f) return x;
  if (x < -20.f) return std::exp(x);  // == log1p(exp(x)) to fp32 precision
  return std::log1p(std::exp(x));
}

}  // namespace

void gate(const uint16_t* ba, const float* A, const float* dt_bias,
          float* ab, int nv) {
  for (int h = 0; h < nv; ++h) {
    const float b = h2f(ba[h]);              // b part: rows [0, nv)
    const float a = h2f(ba[nv + h]);         // a part: rows [nv, 2*nv)
    const float beta = sigmoidf(b);                       // C-GDN-2
    const float dt = softplusf(a + dt_bias[h]);
    const float g = A[h] * dt;   // A = -exp(A_log) pre-negated (C-GDN-3)
    ab[h] = std::exp(g);                                  // alpha
    ab[nv + h] = beta;
  }
}

void conv_step(uint16_t* conv_out, uint16_t* conv_state, const uint16_t* proj,
               const uint16_t* w, const uint16_t* b, int conv_dim, int ck) {
  // window = [state (ck-1 previous raw inputs) | x (current)]
  std::vector<float> win(ck);
  for (int d = 0; d < conv_dim; ++d) {
    for (int j = 0; j < ck - 1; ++j) win[j] = h2f(conv_state[d * (ck - 1) + j]);
    win[ck - 1] = h2f(proj[d]);
    float acc = h2f(b[d]);
    for (int j = 0; j < ck; ++j) acc += h2f(w[d * ck + j]) * win[j];
    conv_out[d] = f2h(acc / (1.f + std::exp(-acc)));  // SiLU = x*sigmoid(x)
    // shift state left, append current raw input
    for (int j = 0; j < ck - 2; ++j)
      conv_state[d * (ck - 1) + j] = conv_state[d * (ck - 1) + j + 1];
    conv_state[d * (ck - 1) + ck - 2] = proj[d];
  }
}

void l2_norm(uint16_t* qn, uint16_t* kn, const uint16_t* conv_out,
             int nk, int K, float eps) {
  const int off_k = nk * K;  // k part starts after the q part in conv_out
  for (int h = 0; h < nk; ++h) {
    // per-head L2: y = x / sqrt(sum(x^2) + eps)  (C-GDN-1, no weight)
    auto norm_head = [&](const uint16_t* src, uint16_t* dst) {
      float ss = 0.f;
      for (int i = 0; i < K; ++i) {
        const float v = h2f(src[h * K + i]);
        ss += v * v;
      }
      const float inv = 1.f / std::sqrt(ss + eps);
      for (int i = 0; i < K; ++i)
        dst[h * K + i] = f2h(h2f(src[h * K + i]) * inv);
    };
    norm_head(conv_out, qn);
    norm_head(conv_out + off_k, kn);
  }
}

void delta_step(float* state, uint16_t* y, const uint16_t* qn,
                const uint16_t* kn, const uint16_t* v, const float* ab,
                int nk, int K, int ratio, int V) {
  const int rows = ratio * V;
  const int nv = nk * ratio;
  for (int h = 0; h < nk; ++h) {
    float* S = state + static_cast<size_t>(h) * rows * K;
    // per-head normalized q/k (fp16 in, fp32 math)
    std::vector<float> q(K), k(K);
    for (int i = 0; i < K; ++i) {
      q[i] = h2f(qn[h * K + i]);
      k[i] = h2f(kn[h * K + i]);
    }
    // v slice: this k-head owns `ratio` consecutive v-heads, concatenated
    const uint16_t* v_h = v + static_cast<size_t>(h) * rows;
    // u_j = S[j,:] . k
    std::vector<float> u(rows);
    for (int j = 0; j < rows; ++j) {
      float acc = 0.f;
      for (int i = 0; i < K; ++i) acc += S[static_cast<size_t>(j) * K + i] * k[i];
      u[j] = acc;
    }
    // S <- alpha*S - alpha*beta*u k^T + beta*v k^T ; y_j = S_new[j,:] . q
    // alpha/beta are PER V-HEAD: value row j of k-head h belongs to
    // v-head h*ratio + j/V (ab layout: {alpha[nv] | beta[nv]}).
    for (int j = 0; j < rows; ++j) {
      const int vh = h * ratio + j / V;
      const float alpha = ab[vh];
      const float beta = ab[nv + vh];
      const float vj = h2f(v_h[j]);
      float yj = 0.f;
      for (int i = 0; i < K; ++i) {
        float& s = S[static_cast<size_t>(j) * K + i];
        s = alpha * s - alpha * beta * u[j] * k[i] + beta * vj * k[i];  // C-GDN-4
        yj += s * q[i];
      }
      y[static_cast<size_t>(h) * rows + j] = f2h(yj);
    }
  }
}

void out_norm(uint16_t* out, const uint16_t* y, const uint16_t* z,
              const uint16_t* w_on, int nv, int V, float eps) {
  for (int w = 0; w < nv; ++w) {
    float ss = 0.f;
    for (int i = 0; i < V; ++i) {
      const float v = h2f(y[static_cast<size_t>(w) * V + i]);
      ss += v * v;
    }
    const float inv = 1.f / std::sqrt(ss / static_cast<float>(V) + eps);
    for (int i = 0; i < V; ++i) {
      const float n = h2f(y[static_cast<size_t>(w) * V + i]) * inv *
                      h2f(w_on[i]);
      const float zg = h2f(z[static_cast<size_t>(w) * V + i]);
      const float silu = zg / (1.f + std::exp(-zg));  // silu(z) = z*sigmoid(z)
      out[static_cast<size_t>(w) * V + i] = f2h(n * silu);   // C-GDN-6
    }
  }
}

}  // namespace sager::gdn_cpu
